async function loadWorkflowDetail(id,version){try{const [data,list]=await Promise.all([api('/admin/api/workflows/'+encodeURIComponent(id)+'/'+encodeURIComponent(String(version))),api('/admin/api/workflows')]);if(location.hash!=='#workflow/'+encodeURIComponent(id)+'/'+version&&location.hash!=='#workflow/'+id+'/'+version)return;const versions=(list.workflows||[]).filter(w=>w.workflowId===id);renderWorkflowDetail(data.workflow,versions)}catch(e){showState('globalState',e.message,'error')}}function workflowStepsText(steps){return (steps||[]).map(step=>[step.id,step.evidenceType,step.timeoutMs,(step.argv||[]).join(' ')].join(' | ')).join('\\n')}
function parseWorkflowSteps(text){return text.split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean).map((line,index)=>{const parts=line.split('|').map(x=>x.trim());if(parts.length<4)throw new Error('验证步骤第 '+(index+1)+' 行格式错误，应为：ID | evidenceType | timeoutMs | 命令及参数');const argv=parts.slice(3).join('|').trim().split(/\\s+/).filter(Boolean);if(!argv.length)throw new Error('验证步骤第 '+(index+1)+' 行缺少命令');return {id:parts[0],type:'command',evidenceType:parts[1],timeoutMs:Number(parts[2]),argv}})}
function workflowDefinitionFromForm(){const form=$('workflowForm');let base={};try{base=JSON.parse(form.elements.definition.value||'{}')}catch{throw new Error('高级 Policy JSON 不是有效 JSON')}const changeMode=form.elements.changeMode.value;const codeChange=changeMode==='code_change';const completion=[];if(form.elements.requireAttemptSucceeded.checked)completion.push('latest_work_attempt_succeeded');if(form.elements.requireEvidencePassed.checked)completion.push('required_evidence_passed');if(form.elements.requireNoBlocker.checked)completion.push('no_unresolved_blocker');if(form.elements.requireReviewAccepted.checked||codeChange)completion.push('review_accepted');const publication=form.elements.requirePublication.checked||codeChange;const changeRequest=form.elements.requireChangeRequest.checked||codeChange;if(publication)completion.push('publication_succeeded');if(changeRequest)completion.push('change_request_created');const approval=!codeChange&&form.elements.requireApproval.checked;if(approval)completion.push('required_approvals_approved');const reviewRequired=codeChange||form.elements.reviewRequired.checked;const requiredEvidence=form.elements.requiredEvidence.value.split(',').map(x=>x.trim()).filter(Boolean);if(codeChange){for(const type of ['build','unit_test'])if(!requiredEvidence.includes(type))requiredEvidence.push(type)}const definition={...base,lifecycle:{...(base.lifecycle||{}),attempt:{...((base.lifecycle||{}).attempt||{}),maxWorkAttempts:Number(form.elements.maxWorkAttempts.value),maxReworks:Number(form.elements.maxReworks.value)},continuation:{...((base.lifecycle||{}).continuation||{}),maxTurnsPerRun:Number(form.elements.maxTurnsPerRun.value)},retry:{...((base.lifecycle||{}).retry||{}),failure:{...(((base.lifecycle||{}).retry||{}).failure||{}),enabled:form.elements.retryEnabled.checked,maxRunsPerWorkAttempt:Number(form.elements.maxRunsPerWorkAttempt.value),initialBackoffMs:((base.lifecycle||{}).retry?.failure?.initialBackoffMs??1000),maxBackoffMs:((base.lifecycle||{}).retry?.failure?.maxBackoffMs??30000)}},blocked:{...((base.lifecycle||{}).blocked||{}),timeoutPolicy:'manual'}},execution:{...(base.execution||{}),workspace:{...((base.execution||{}).workspace||{}),strategy:'isolated',reuseOnContinuation:true,cleanup:form.elements.cleanup.value}},validation:{...(base.validation||{}),requiredEvidence,required:parseWorkflowSteps(form.elements.verificationSteps.value)},review:{required:reviewRequired,...(form.elements.reviewerExpertId.value.trim()?{reviewerExpertId:form.elements.reviewerExpertId.value.trim()}:{})},completion:{...(base.completion||{}),require:completion},graph:{...(base.graph||{}),mode:'single-node'}};if(changeMode)definition.change={mode:changeMode,...(codeChange?{delivery:'merge_request'}:{})};else delete definition.change;const runtime=form.elements.requiredRuntimeProfile.value;if(runtime)definition.execution.requiredRuntimeProfile=runtime;else delete definition.execution.requiredRuntimeProfile;if(approval)definition.completion.requiredApprovals=[publication?{scope:'publish_work_branch',subjectType:'publication_artifact'}:{scope:'work_completion',subjectType:'workspace_revision'}];else delete definition.completion.requiredApprovals;if(publication)definition.publication={...(base.publication||{}),required:true,mode:'work_branch',approvalRequired:approval};else delete definition.publication;return definition}
function loadWorkflowDefinitionIntoForm(definition){const form=$('workflowForm');const d=definition||{};form.elements.changeMode.value=d.change?.mode||'';form.elements.maxWorkAttempts.value=String(d.lifecycle?.attempt?.maxWorkAttempts??5);form.elements.maxReworks.value=String(d.lifecycle?.attempt?.maxReworks??3);form.elements.maxRunsPerWorkAttempt.value=String(d.lifecycle?.retry?.failure?.maxRunsPerWorkAttempt??3);form.elements.maxTurnsPerRun.value=String(d.lifecycle?.continuation?.maxTurnsPerRun??20);form.elements.retryEnabled.checked=d.lifecycle?.retry?.failure?.enabled!==false;form.elements.cleanup.value=d.execution?.workspace?.cleanup||'on_terminal';form.elements.requiredRuntimeProfile.value=d.execution?.requiredRuntimeProfile||'';form.elements.requiredEvidence.value=(d.validation?.requiredEvidence||['expert_result']).join(',');form.elements.verificationSteps.value=workflowStepsText(d.validation?.required||[]);form.elements.reviewRequired.checked=d.review?.required!==false;form.elements.reviewerExpertId.value=d.review?.reviewerExpertId||'';const require=new Set(d.completion?.require||[]);form.elements.requireAttemptSucceeded.checked=require.has('latest_work_attempt_succeeded');form.elements.requireEvidencePassed.checked=require.has('required_evidence_passed');form.elements.requireNoBlocker.checked=require.has('no_unresolved_blocker');form.elements.requireReviewAccepted.checked=require.has('review_accepted');form.elements.requireApproval.checked=require.has('required_approvals_approved');form.elements.requirePublication.checked=require.has('publication_succeeded')||d.publication?.required===true;form.elements.requireChangeRequest.checked=require.has('change_request_created');form.elements.definition.value=JSON.stringify(d,null,2)}
