$('workRefresh').onclick=()=>{workOffset=0;void loadWorkList()};async function submitWorkReview(decision){if(!workSelected||!workDetailSnapshot)return;const work=workDetailSnapshot.work||{};const reason=$('workReviewReason').value.trim();if((decision==='rework'||decision==='rejected')&&!reason){$('workReviewState').textContent='要求返工或拒绝时必须填写原因。';return}const labels={accepted:'通过',rework:'要求返工',rejected:'拒绝'};if(decision==='rejected'&&!confirm('确定拒绝该 Work？拒绝后该工作会进入 failed。'))return;try{for(const id of ['workReviewAccept','workReviewRework','workReviewReject'])$(id).disabled=true;$('workReviewState').textContent='正在提交“'+labels[decision]+'”…';const data=await api('/admin/api/work-items/'+encodeURIComponent(workSelected)+'/review',{method:'POST',body:JSON.stringify({expectedRevision:work.stateRevision,subjectRevision:work.currentSubjectRevision,decision,...(reason?{reason}:{})})});$('workActionState').textContent='审核已提交：'+labels[decision];renderWorkDetail(data)}catch(e){$('workReviewState').textContent=e.message}finally{for(const id of ['workReviewAccept','workReviewRework','workReviewReject'])$(id).disabled=false}}$('workReviewAccept').onclick=()=>void submitWorkReview('accepted');$('workReviewRework').onclick=()=>void submitWorkReview('rework');$('workReviewReject').onclick=()=>void submitWorkReview('rejected');$('workPrev').onclick=()=>{workOffset=Math.max(0,workOffset-20);void loadWorkList()};$('workNext').onclick=()=>{workOffset+=20;void loadWorkList()};$('workStatus').onchange=()=>{workOffset=0;void loadWorkList()};$('workQuery').onchange=()=>{workOffset=0;void loadWorkList()};$('workBack').onclick=()=>{location.hash='work-items'};$('workDetailRefresh').onclick=()=>{if(workSelected)void loadWorkDetail(workSelected)};$('workReconcile').onclick=async()=>{if(!workSelected)return;try{const data=await api('/admin/api/work-items/'+encodeURIComponent(workSelected)+'/reconcile',{method:'POST'});$('workActionState').textContent='Reconcile 完成';renderWorkDetail(data)}catch(e){$('workActionState').textContent=e.message}};$('workResume').onclick=async()=>{if(!workSelected)return;try{const data=await api('/admin/api/work-items/'+encodeURIComponent(workSelected)+'/resume',{method:'POST'});$('workActionState').textContent='WorkItem 已恢复';renderWorkDetail(data)}catch(e){$('workActionState').textContent=e.message}};$('workCancel').onclick=async()=>{if(!workSelected||!confirm('确定取消该 WorkItem？当前活动 Expert Task 也会被取消。'))return;try{const data=await api('/admin/api/work-items/'+encodeURIComponent(workSelected)+'/cancel',{method:'POST'});$('workActionState').textContent='WorkItem 已取消';renderWorkDetail(data)}catch(e){$('workActionState').textContent=e.message}};
