function friendlyMetricValue(value,fallback='未记录'){return value==null||String(value).trim()===''||String(value)==='unknown'?fallback:String(value)}
function renderTaskFeedbackMetrics(groups){const summary=$('taskFeedbackSummary');const rows=$('taskFeedbackMetrics');summary.replaceChildren();rows.replaceChildren();const totals=(groups||[]).reduce((acc,g)=>{acc.successful+=Number(g.successful||0);acc.reviewed+=Number(g.reviewed||0);acc.adopted+=Number(g.adopted||0);acc.partiallyAdopted+=Number(g.partiallyAdopted||0);acc.rework+=Number(g.rework||0);return acc},{successful:0,reviewed:0,adopted:0,partiallyAdopted:0,rework:0});const adoptionRate=totals.reviewed?Math.round(((totals.adopted+totals.partiallyAdopted)/totals.reviewed)*100):null;for(const item of [['成功任务',totals.successful,''],['已反馈',totals.reviewed,''],['采纳率',adoptionRate==null?'—':adoptionRate+'%',''],['需返工',totals.rework,totals.rework>0?'warn':'']]){const box=document.createElement('div');box.className='feedback-stat'+(item[2]?' '+item[2]:'');const label=document.createElement('span');label.className='label';label.textContent=String(item[0]);const value=document.createElement('strong');value.textContent=String(item[1]);box.append(label,value);summary.append(box)}if(!(groups||[]).length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=10;td.className='empty';td.textContent='暂无成功任务反馈统计';tr.append(td);rows.append(tr);return}for(const g of groups){const tr=document.createElement('tr');const rate=g.adoptionRate==null?null:Math.round(Number(g.adoptionRate)*100);const values=[friendlyMetricValue(g.expertId,'历史任务'),friendlyMetricValue(g.deploymentId),g.deploymentConfigVersion==null||String(g.deploymentConfigVersion)==='unknown'?'—':'v'+String(g.deploymentConfigVersion),String(g.successful),String(g.reviewed)+' / '+String(g.successful),String(g.adopted),String(g.partiallyAdopted),String(g.notAdopted),String(g.rework)];values.forEach((value,index)=>{const td=document.createElement('td');td.textContent=value;if((index===1&&value==='未记录')||(index===2&&value==='—'))td.className='feedback-cell-muted';tr.append(td)});const rateCell=document.createElement('td');rateCell.className='feedback-rate';const rateText=document.createElement('span');rateText.textContent=rate==null?'—':rate+'%';rateCell.append(rateText);if(rate!=null){const track=document.createElement('div');track.className='feedback-rate-track';const fill=document.createElement('div');fill.className='feedback-rate-fill';fill.style.width=Math.max(0,Math.min(100,rate))+'%';track.append(fill);rateCell.append(track)}tr.append(rateCell);rows.append(tr)}}
function renderTaskFeedback(task,feedback){const root=$('taskFeedback');root.replaceChildren();if(!feedback){root.className='muted';root.textContent=task.status==='succeeded'?'未反馈':'仅成功任务可反馈';return}root.className='feedback-panel';const dispositionLabels={adopted:'已采纳',partially_adopted:'部分采纳',not_adopted:'未采纳'};const fields=[['采纳状态',dispositionLabels[feedback.disposition]||String(feedback.disposition)],['是否返工',feedback.needsRework==null?'未说明':feedback.needsRework?'需要返工':'无需返工'],['反馈时间',new Date(Number(feedback.updatedAt)).toLocaleString()]];for(const [labelText,valueText] of fields){const box=document.createElement('div');const label=document.createElement('span');label.className='label';label.textContent=labelText;const value=document.createElement('span');value.className='value';value.textContent=String(valueText);box.append(label,value);root.append(box)}const reason=document.createElement('div');reason.className='wide';const reasonLabel=document.createElement('span');reasonLabel.className='label';reasonLabel.textContent='反馈原因';const reasonValue=document.createElement('span');reasonValue.className='value reason';reasonValue.textContent=String(feedback.reason??'未填写');reason.append(reasonLabel,reasonValue);root.append(reason)}
async function loadTaskList(){
  try { const params=new URLSearchParams({limit:'20',offset:String(taskOffset)});
    for(const [key,id] of [['status','taskStatus'],['expertId','taskExpert'],['workerId','taskWorker'],['q','taskQuery']]){const value=$(id).value.trim();if(value)params.set(key,value)}
    const data=await api('/admin/api/expert-tasks?'+params);$('taskRows').replaceChildren();
    for(const item of data.tasks||[]){const tr=document.createElement('tr');const timeCell=document.createElement('td');timeCell.textContent=item.created_at==null?'—':new Date(Number(item.created_at)).toLocaleString();timeCell.title=item.created_at==null?'历史任务没有可用的创建时间':new Date(Number(item.created_at)).toISOString();tr.appendChild(timeCell);for(const key of ['task_id','expert_id','repository_id','worker_id','status','selection_mode']){const td=document.createElement('td');td.textContent=String(item[key]??'—');tr.appendChild(td)}const td=document.createElement('td');const btn=document.createElement('button');btn.textContent='详情';btn.onclick=()=>{location.hash='task/'+encodeURIComponent(item.task_id)};td.append(btn);tr.append(td);$('taskRows').append(tr)}
    $('taskSummary').textContent='总计 '+data.total+' 条 · 当前偏移 '+data.offset;renderTaskFeedbackMetrics(data.feedbackMetrics||[]);$('taskPrev').disabled=taskOffset===0;$('taskNext').disabled=taskOffset+20>=data.total;
  }catch(e){$('taskSummary').textContent=e.message}
}
async function loadTaskDetail(id){try{const data=await api('/admin/api/expert-tasks/'+encodeURIComponent(id)+'?limit='+taskEventLimit+'&offset='+taskEventOffset);if(location.hash!=='#task/'+id)return;taskSelected=id;
  const task=data.task||{};$('taskDetail').replaceChildren();for(const key of ['task_id','work_item_id','principal_id','scope','source_client','source_session_id','expert_id','repository_id','repository_url','repository_branch','commit_sha','deployment_id','deployment_config_version','worker_id','run_id','fencing','status','selection_mode','problem']){const box=document.createElement('p');box.textContent=key+': '+String(task[key]??'—');$('taskDetail').append(box)}
  if(task.deployment_snapshot_json){try{const snap=JSON.parse(task.deployment_snapshot_json);for(const [name,value] of [['executor_backend',snap.executor?.backend],['executor_model',snap.executor?.modelConfig?.model],['mcp_profile',snap.mcp?.profileRef],['mcp_required',snap.mcp?.required],['mcp_allowed_tools',snap.mcp?.allowedTools?.join(', ')]]){const box=document.createElement('p');box.textContent=name+': '+String(value??'—');$('taskDetail').append(box)}}catch{}}
  renderChangeRequest('taskChangeRequest',data.changeRequest,data.work||{workItemId:task.work_item_id});
  $('taskRuns').textContent=(data.runs||[]).map(r=>r.run_id+' / '+r.worker_id+' / fencing='+r.fencing+' / '+r.status).join('；')||'无';$('taskEvents').replaceChildren();for(const e of data.events||[]){const tr=document.createElement('tr');for(const v of [new Date(Number(e.created_at)).toLocaleString(),e.run_id||'—',e.event_type,e.event_type==='tool.activity'?(String(e.tool_code||'other')+' ×'+String(e.count||1)):(e.details||'')]){const td=document.createElement('td');td.textContent=String(v);tr.append(td)}$('taskEvents').append(tr)}const ep=data.eventsPage||{total:0,limit:taskEventLimit,offset:taskEventOffset,hasNewer:false,hasOlder:false};$('taskEventsPage').textContent='共 '+ep.total+' 条 · '+(ep.total?(ep.offset+1)+'-'+(ep.offset+(data.events||[]).length):'0')+' · 最新在前';$('taskEventsNewer').disabled=!ep.hasNewer;$('taskEventsOlder').disabled=!ep.hasOlder;
  renderTaskFeedback(task,data.feedback);
  $('taskReport').textContent=String(task.result||'尚无结果');
  $('taskStop').disabled=!['queued','running'].includes(task.status)||Boolean(task.cancellation_requested);
  $('taskStop').textContent=task.cancellation_requested?'停止已请求':'停止任务';
  $('taskDelete').disabled=!['succeeded','failed','cancelled'].includes(task.status);
}catch(e){$('taskSummary').textContent=e.message}}
$('taskRefresh').onclick=()=>{taskOffset=0;loadTaskList()};
$('taskPrev').onclick=()=>{taskOffset=Math.max(0,taskOffset-20);loadTaskList()};$('taskNext').onclick=()=>{taskOffset+=20;loadTaskList()};
for(const id of ['taskStatus','taskExpert','taskWorker','taskQuery'])$(id).onchange=()=>{taskOffset=0;loadTaskList()};
function routeTaskPage(){const match=new RegExp('^#task/([a-f0-9-]{36})$','i').exec(location.hash);
  if(match){if(taskSelected!==match[1])taskEventOffset=0;switchView('taskPage');$('taskActionState').textContent='';void loadTaskDetail(match[1]);}
  else{taskSelected=null;switchView('tasks');void loadTaskList();}}
$('taskBack').onclick=()=>{location.hash='tasks'};
$('taskEventsNewer').onclick=()=>{taskEventOffset=Math.max(0,taskEventOffset-taskEventLimit);if(taskSelected)void loadTaskDetail(taskSelected)};
$('taskEventsOlder').onclick=()=>{taskEventOffset=Math.min(999,taskEventOffset+taskEventLimit);if(taskSelected)void loadTaskDetail(taskSelected)};
$('taskDetailRefresh').onclick=()=>{if(taskSelected)void loadTaskDetail(taskSelected)};
$('taskStop').onclick=async()=>{if(!taskSelected||!confirm('确定停止该任务？运行中的任务会发送取消请求，Worker 确认后才会结束。'))return;
  try{const result=await api('/admin/api/expert-tasks/'+encodeURIComponent(taskSelected)+'/stop',{method:'POST'});
    $('taskActionState').textContent=result.outcome==='cancelled'?'任务已取消':'停止请求已提交，等待 Worker 确认';await loadTaskDetail(taskSelected);
  }catch(e){$('taskActionState').textContent=e.message}};
$('taskDelete').onclick=async()=>{if(!taskSelected||!confirm('确定永久删除该任务及所有 Run、事件、报告？此操作不可恢复。'))return;
  try{await api('/admin/api/expert-tasks/'+encodeURIComponent(taskSelected),{method:'DELETE'});location.hash='tasks';}
  catch(e){$('taskActionState').textContent=e.message}};
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#task/')||location.hash==='#tasks')routeTaskPage()});
